scriptdefs
= RustboroCity_Gym_EventScript_Marc
trainerbattle_single TRAINER_MARC RustboroCity_Gym_Text_MarcIntro RustboroCity_Gym_Text_MarcDefeat
msgbox	Das muss ich unserer LEITERIN lassen.Es brauchte Köpfchen und Gespür, dass sie in jungen Jahren den GESTEIN-Typ gewählt hat.
end
= RustboroCity_Gym_EventScript_GymGuide
lock
faceplayer
goto_if_set FLAG_DEFEATED_RUSTBORO_GYM RustboroCity_Gym_EventScript_GymGuidePostVictory
msgbox	Yo, wie geht's?Hör mal, mein Freund! Möchtest du CHAMP werden?Ich bin kein TRAINER, nein, aber ich kann dir bestimmt siegreiche Tipps geben.Also abgemacht! Wir peilen gemeinsam die POKéMON-MEISTERSCHAFT an!Es ist deine Aufgabe als TRAINER, ARENA-ORDEN zu sammeln, stimmt's?Aber ARENALEITER sind keine leichte Beute!Und genau da komme ich ins Spiel! Ich bin hier, um dir Expertenrat zu geben!ROXANNE, die ARENALEITERIN, setzt GESTEIN-POKéMON ein.Der GESTEIN-Typ ist sehr widerstandsfähig, kann aber WASSER- und PFLANZE-Attacken nicht ab.Besuch mich danach, falls du die ARENALEITERIN besiegst.Na dann, leg los!
release
end
= RustboroCity_Gym_EventScript_GymGuidePostVictory
msgbox	Wow! Was für ein atemberaubender Sieg! Mein Anfeuern muss geholfen haben!Toll! Sieh dir deine TRAINERKARTE an.Der STEIN-ORDEN, den du bekommen hast, sollte dort ordentlich vermerkt sein.Mit anderen Worten…Du hast die erste Stufe auf der Treppe zur MEISTERSCHAFT erklommen!Das muss sich großartig anfühlen!
release
end
= RustboroCity_Gym_EventScript_Tommy
trainerbattle_single TRAINER_TOMMY RustboroCity_Gym_Text_TommyIntro RustboroCity_Gym_Text_TommyDefeat
msgbox	ROXANNE ist um einiges stärker als ich.Du solltest besser auf der Hut sein!
end
= RustboroCity_Gym_EventScript_Josh
trainerbattle_single TRAINER_JOSH RustboroCity_Gym_Text_JoshIntro RustboroCity_Gym_Text_JoshDefeat
msgbox	Du hast noch gar nichts von der furchterregenden Kraft des GESTEIN-Typs gesehen!
end
= RustboroCity_Gym_EventScript_Roxanne
trainerbattle_single TRAINER_ROXANNE_1 RustboroCity_Gym_Text_RoxanneIntro RustboroCity_Gym_Text_RoxanneDefeat RustboroCity_Gym_EventScript_RoxanneDefeated NO_MUSIC
specialvar VAR_RESULT ShouldTryRematchBattle
goto_if_eq VAR_RESULT TRUE RustboroCity_Gym_EventScript_RoxanneRematch
goto_if_unset FLAG_RECEIVED_TM_ROCK_TOMB RustboroCity_Gym_EventScript_GiveRockTomb
msgbox	Da du so stark bist, solltest du dich auch anderen ARENALEITERN stellen.Wenn du gegen viele TRAINER kämpfst, wirst du viel lernen.
release
end
= RustboroCity_Gym_EventScript_GiveRockTomb
giveitem ITEM_TM_ROCK_TOMB
goto_if_eq VAR_RESULT FALSE Common_EventScript_ShowBagIsFull
setflag FLAG_RECEIVED_TM_ROCK_TOMB
msgbox	Diese TECHNISCHE MASCHINE, TM39, enthält GERÖLLGRAB.Sie fügt nicht nur Schaden durch fallende Felsen zu, sondern senkt auch die INITIATIVE.Wenn du eine TM benutzt, bringt sie einem POKéMON die Attacke sofort bei.Denk daran, eine TM kann nur einmal benutzt werden, überlege es dir also gut.
release
end
= RustboroCity_Gym_EventScript_RoxanneRematch
trainerbattle_rematch_double TRAINER_ROXANNE_1 RustboroCity_Gym_Text_RoxannePreRematch RustboroCity_Gym_Text_RoxanneRematchDefeat RustboroCity_Gym_Text_RoxanneRematchNeedTwoMons
msgbox	ROXANNE: Ich habe noch viel über POKéMON-Kämpfe zu lernen.Diese Erkenntnis lässt mich das Kämpfen nur noch mehr lieben!
end
= RustboroCity_Gym_EventScript_RoxanneDefeated
msgbox	PLAYER hat von ROXANNE den STEIN-ORDEN erhalten.
waitmessage
call Common_EventScript_PlayGymBadgeFanfare
msgbox	Der STEIN-ORDEN erhöht die ANGRIFF-Stärke deiner POKéMON.Außerdem ermöglicht er ihnen, die VM-Attacke ZERSCHNEIDER außerhalb von Kämpfen einzusetzen.Bitte nimm auch das hier mit.
setflag FLAG_DEFEATED_RUSTBORO_GYM
setflag FLAG_BADGE01_GET
setvar VAR_RUSTBORO_CITY_STATE 1
addvar VAR_PETALBURG_GYM_STATE 1
setvar VAR_0x8008 1
call Common_EventScript_SetGymTrainers
call_if_eq VAR_PETALBURG_GYM_STATE 6 Common_EventScript_ReadyPetalburgGymForBattle
goto RustboroCity_Gym_EventScript_GiveRockTomb
end
